Think: Validate each listed file: skip the file list itself, report the directory, check that each student file has exactly four tokens and three numeric scores; write valid filenames to temp_workspace/valid_files.txt and errors to temp_workspace/errors.log.

Act: bash

```bash
awk 'BEGIN{errs="temp_workspace/errors.log"; val="temp_workspace/valid_files.txt"; system("rm -f " errs " " val)} 
{
 fname=$0
 if(fname=="" ) next
 if(fname=="file_list.txt") next
 if(fname=="student_data"){ print fname " is a directory" >> errs; next }
 # read first non-empty line from the file
 line=""
 while((getline l < fname) > 0){ if(l ~ /[^[:space:]]/) { line=l; break } }
 close(fname)
 if(line==""){ print fname " is empty or unreadable" >> errs; next }
 n=split(line, a, /[[:space:]]+/)
 if(n!=4){ print fname " has " n " tokens (expected 4)" >> errs; next }
 ok=1
 for(i=2;i<=4;i++){ if(a[i]!~/^[-+]?[0-9]+(\.[0-9]+)?$/){ ok=0; break } }
 if(ok) print fname >> val
 else print fname " has non-numeric score(s)" >> errs
}' temp_workspace/file_list.txt
```

