Think: Build temp_workspace/per_file_counts.csv by reading each filename from temp_workspace/file_list.txt and pulling counts from the corresponding .meta files.

Act: bash

```bash
awk '{
  fname=$0;
  lfile="temp_workspace/lines_" fname ".meta";
  wfile="temp_workspace/words_" fname ".meta";
  linecount="0";
  wordcount="0";
  if ((getline lc < lfile) > 0) linecount=lc;
  close(lfile);
  if ((getline wc < wfile) > 0) wordcount=wc;
  close(wfile);
  printf "%s,%s,%s\n", fname, linecount, wordcount;
}' temp_workspace/file_list.txt > temp_workspace/per_file_counts.csv
