Think: Fix the awk syntax error by using a correctly formatted awk program to group entries by inode and produce duplicates.tsv.

Act: bash

```bash
awk -F'\t' '{
 inode=$1; path=$4; if(path=="") path=$0;
 if (inode in grp) grp[inode]=grp[inode]"|"path; else grp[inode]=path;
 cnt[inode]++;
}
END {
 for (i in cnt) {
  t = (cnt[i] > 1 ? "single_object" : "separate_entry");
  print i"\t"cnt[i]"\t"grp[i]"\t"t;
 }
}' temp_var_count/file_metadata.tsv > temp_var_count/duplicates.tsv
